#!/usr/bin/env python3
"""
PNG -> LVGL 9 C image in RGB565A8 (the robot head's format), with no Python packages:
ImageMagick decodes the PNG to raw RGBA, this script packs it.

    python3 tools/png_to_lvgl.py main/assets/logo_claude.png img_logo_claude

Writes main/assets/<name>.c next to the PNG. RGB565A8 = a little-endian RGB565 plane
(stride w*2) followed by an 8-bit alpha plane.
"""
import subprocess
import sys
from pathlib import Path

TEMPLATE = """\
/* Generated by tools/png_to_lvgl.py from {png}: {w}x{h} RGB565A8. */
#include "lvgl.h"

static const uint8_t {name}_map[] = {{
{data}
}};

const lv_image_dsc_t {name} = {{
    .header = {{
        .magic = LV_IMAGE_HEADER_MAGIC,
        .cf = LV_COLOR_FORMAT_RGB565A8,
        .w = {w},
        .h = {h},
        .stride = {stride},
    }},
    .data_size = sizeof({name}_map),
    .data = {name}_map,
}};
"""


def main() -> None:
    png, name = Path(sys.argv[1]), sys.argv[2]
    size = subprocess.run(["magick", "identify", "-format", "%w %h", str(png)],
                          check=True, capture_output=True, text=True).stdout
    w, h = map(int, size.split())
    rgba = subprocess.run(["magick", str(png), "-depth", "8", "rgba:-"], check=True, capture_output=True).stdout
    assert len(rgba) == w * h * 4, "unexpected pixel data size"

    color, alpha = bytearray(), bytearray()
    for i in range(0, len(rgba), 4):
        r, g, b, a = rgba[i:i + 4]
        rgb565 = ((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3)
        color += rgb565.to_bytes(2, "little")
        alpha.append(a)
    raw = color + alpha

    lines = [", ".join(f"0x{byte:02x}" for byte in raw[i:i + 16]) + "," for i in range(0, len(raw), 16)]
    out = png.with_name(f"{name}.c")
    out.write_text(TEMPLATE.format(png=png.name, name=name, w=w, h=h, stride=w * 2,
                                   data="\n".join("    " + line for line in lines)))
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
